using System;using System.IO;using System.Text;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;
class FixtureRunner {
 static string Root=AppDomain.CurrentDomain.BaseDirectory,Folder=Path.Combine(Root,"lifecycle-fixture"),Data=Path.Combine(Folder,"profile");static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=2097152};
 static void Save(string name,object value){File.WriteAllText(Path.Combine(Root,name),J.Serialize(value),new UTF8Encoding(false));}
 static void Wait(string name,Process child,int max){var w=Stopwatch.StartNew();while(!File.Exists(Path.Combine(Data,name))&&w.ElapsedMilliseconds<max){if(child.HasExited)throw new Exception("fixture exited before "+name+"; code="+child.ExitCode);Thread.Sleep(50);}if(!File.Exists(Path.Combine(Data,name)))throw new Exception("timeout waiting for "+name);}
 static object Sample(string checkpoint){var ids=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Data,checkpoint)));var pids=new[]{Convert.ToInt32(ids["mainPID"]),Convert.ToInt32(ids["brokerPID"])}.Where(x=>x>0).ToArray();var ps=pids.Select(Process.GetProcessById).ToArray();try{long[] start=ps.Select(p=>p.TotalProcessorTime.Ticks).ToArray(),last=(long[])start.Clone();int cpus=Environment.ProcessorCount;var w=Stopwatch.StartNew();double prev=0,peak=0;var samples=new List<object>();for(int x=0;x<30;x++){Thread.Sleep(1000);double now=w.Elapsed.TotalSeconds,delta=0;var rows=new List<object>();for(int i=0;i<ps.Length;i++){ps[i].Refresh();long cpu=ps[i].TotalProcessorTime.Ticks;double d=(cpu-last[i])/10000000.0;last[i]=cpu;delta+=d;rows.Add(new{PID=ps[i].Id,MachineCPUPercent=100*d/(cpus*(now-prev))});}double total=100*delta/(cpus*(now-prev));peak=Math.Max(peak,total);samples.Add(new{ElapsedSeconds=now,TotalMachineCPUPercent=total,Processes=rows});prev=now;}double elapsed=w.Elapsed.TotalSeconds;var entries=new List<object>();long ws=0,priv=0,ticks=0;for(int i=0;i<ps.Length;i++){var p=ps[i];p.Refresh();ws+=p.WorkingSet64;priv+=p.PrivateMemorySize64;ticks+=p.TotalProcessorTime.Ticks-start[i];entries.Add(new{PID=p.Id,Name=p.ProcessName,Path=p.MainModule.FileName,WorkingSetBytes=p.WorkingSet64,PrivateCommittedBytes=p.PrivateMemorySize64});}return new{SampleSeconds=elapsed,LogicalProcessors=cpus,Processes=entries,WorkingSetBytes=ws,PrivateCommittedBytes=priv,AverageMachineCPUPercent=100*(ticks/10000000.0)/(elapsed*cpus),PeakOneSecondMachineCPUPercent=peak,Samples=samples,NoMicrophone=true,NoWinH=true,Scope="Isolated no-input fixture main and real unmodified UIA broker only; no hooks or real panel. Not recording/recognition load."};}finally{foreach(var p in ps)p.Dispose();}}
 public static int Main(string[] a){try{if(a.Length!=1)throw new Exception("Exact AHK runtime path required");Directory.CreateDirectory(Data);var info=new ProcessStartInfo(a[0],"/ErrorStdOut \""+Path.Combine(Folder,"BrokerLifecycleFixture.ahk")+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Folder,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["WIN_VOICE_HOTKEY_DATA_DIR"]=Data;info.EnvironmentVariables.Remove("WIN_VOICE_HOTKEY_SUPPORT_DIAGNOSTICS");using(var p=Process.Start(info)){var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();Save("fixture-started.json",new{PID=p.Id,UTC=DateTime.UtcNow.ToString("o"),Session=p.SessionId});Wait("active-ready.json",p,15000);Save("fixture-active-measurements.json",Sample("active-ready.json"));File.WriteAllText(Path.Combine(Data,"active-sample-done"),"done");Wait("reclaimed-ready.json",p,20000);Save("fixture-reclaimed-measurements.json",Sample("reclaimed-ready.json"));File.WriteAllText(Path.Combine(Data,"idle-sample-done"),"done");if(!p.WaitForExit(30000))throw new Exception("fixture final tests pending: "+p.Id);File.WriteAllText(Path.Combine(Root,"fixture-stdout.txt"),output.Result);File.WriteAllText(Path.Combine(Root,"fixture-stderr.txt"),error.Result);Save("fixture-completed.json",new{ExitCode=p.ExitCode,UTC=DateTime.UtcNow.ToString("o")});return p.ExitCode;}}catch(Exception e){Save("fixture-runner-error.json",new{Error=e.ToString(),UTC=DateTime.UtcNow.ToString("o")});return 1;}}
}